import { useCallback, useEffect, useRef, useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import { useI18n } from '@/i18n'
import { loadConfig, newConfig, saveConfig, type SyncConfig } from './engine'
import {
  codeHash,
  formatCode,
  isCodeShaped,
  normalizeCode,
  openInvite,
  randomCode,
  sealInvite,
} from './invite'
import { DEFAULT_RELAY, putInvite, takeInvite } from './relay'
import { assertRelayUrl, generateRoomKey, randomRoomId, SyncError } from './packet'

/**
 * Pairing, without the screen around it.
 *
 * Two places need to do this now — the Sync screen and Settings — and pairing
 * is not the kind of logic to have two copies of: one of them would keep the
 * one-shot invite guard and the other would quietly lose it, and the bug would
 * only show up as "kodenya nggak bisa dipakai" on somebody's phone.
 *
 * The hook owns the whole flow: make a code, redeem a code, redeem a code that
 * arrived in a link, and report what state the pairing is in.
 */

export interface Pairing {
  config: SyncConfig | null
  /** The code this phone generated, if it is the one waiting to be joined. */
  code: string | null
  /** Ready-to-share text containing both the link and the code. */
  shareText: string | null
  busy: boolean
  error: string | null
  notice: string | null
  /** True when the build has somewhere to leave the invite. */
  ready: boolean
  create(): Promise<void>
  redeem(raw: string): Promise<void>
  clearMessages(): void
}

export function usePairing(relayOverride?: string, onPaired?: (c: SyncConfig) => void): Pairing {
  const { t } = useI18n()
  const [config, setConfig] = useState<SyncConfig | null>(null)
  const [code, setCode] = useState<string | null>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [notice, setNotice] = useState<string | null>(null)
  const [params, setParams] = useSearchParams()
  // The invite is one-shot: a second attempt after a re-render would fail
  // against a drop that has already been claimed and show an error for
  // something that actually worked.
  const claimed = useRef(false)

  useEffect(() => {
    void loadConfig().then(setConfig)
  }, [])

  const relay = () => (relayOverride?.trim() || DEFAULT_RELAY)

  const redeem = useCallback(
    async (raw: string) => {
      setError(null)
      const clean = normalizeCode(raw)
      if (!isCodeShaped(clean)) {
        setError(t('sync.code.tooShort'))
        return
      }
      let relayUrl: string
      try {
        relayUrl = assertRelayUrl(relay())
      } catch {
        setError(t('sync.relay.missing'))
        return
      }
      setBusy(true)
      try {
        const secret = await openInvite(clean, await takeInvite(relayUrl, await codeHash(clean)))
        const next = newConfig(secret.relayUrl, secret.roomId, secret.keyB64)
        await saveConfig(next)
        setConfig(next)
        onPaired?.(next)
        setNotice(t('sync.join.joined'))
      } catch (e) {
        setNotice(null)
        setError(
          e instanceof SyncError && (e.message === 'invite gone' || e.message === 'invite code')
            ? t('sync.code.gone')
            : t('sync.err.generic'),
        )
      } finally {
        setBusy(false)
      }
    },
    // `t` is stable per locale; `relayOverride` is read through `relay()`.
    // `onPaired` is a setter from the parent and stable in practice.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [t, relayOverride],
  )

  /** A code that arrived in the link, redeemed without anyone typing it. */
  useEffect(() => {
    const fromLink = params.get('kode')
    if (!fromLink || claimed.current || config) return
    claimed.current = true
    params.delete('kode')
    setParams(params, { replace: true })
    void redeem(fromLink)
  }, [params, setParams, config, redeem])

  const create = useCallback(async () => {
    setError(null)
    let relayUrl: string
    try {
      relayUrl = assertRelayUrl(relay())
    } catch {
      setError(t('sync.relay.missing'))
      return
    }
    setBusy(true)
    try {
      const keyB64 = await generateRoomKey()
      const next = newConfig(relayUrl, randomRoomId(), keyB64)
      const fresh = randomCode()
      // Sealed before it is stored, so what reaches the relay is ciphertext
      // under a code the relay never receives.
      await putInvite(
        relayUrl,
        await codeHash(fresh),
        await sealInvite(fresh, { roomId: next.roomId, keyB64, relayUrl }),
      )
      await saveConfig(next)
      setConfig(next)
      onPaired?.(next)
      setCode(fresh)
    } catch {
      setError(t('sync.err.generic'))
    } finally {
      setBusy(false)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [t, relayOverride])

  /**
   * A link is only worth sending from a copy that has a real address.
   *
   * The APK runs the bundle from `file:///android_asset/temudua.html` and the
   * double-click file runs from wherever it was saved, and on both of those
   * `location.origin` is the literal string "null" — a link built from it is
   * dead on arrival. Those copies send the code by itself, which works
   * everywhere because it depends on nothing.
   */
  const linkable = location.protocol === 'http:' || location.protocol === 'https:'

  const shareText = code
    ? linkable
      ? t('sync.code.shareText', {
          code: formatCode(code),
          link: `${location.origin}${import.meta.env.BASE_URL}#/sinkron?kode=${code}`,
        })
      : t('sync.code.shareTextCode', { code: formatCode(code) })
    : null

  return {
    config,
    code,
    shareText,
    busy,
    error,
    notice,
    ready: !!relay(),
    create,
    redeem,
    clearMessages: () => {
      setError(null)
      setNotice(null)
    },
  }
}
