import { SyncError } from './packet'

/**
 * Kode sambung — pairing by typing eight characters.
 *
 * The QR pairing works, but only if the two people are in the same room. They
 * usually are not: one is at the office, one is at home, one is away on a trip.
 * The honest read of that is that the QR is the *rare* case and a code you can
 * send over WhatsApp is the normal one.
 *
 * The code is not a password on a server, and the relay never learns it:
 *
 *   - the phone that starts it invents a code, derives a key from it, and
 *     encrypts `{roomId, roomKey}` with that key;
 *   - it stores the ciphertext under `SHA-256(code)`, which is all the relay
 *     ever sees — a hash it cannot reverse in any useful time, against a blob
 *     it has no key for;
 *   - the other phone types the code, recomputes the same hash to fetch the
 *     blob, and derives the same key to open it.
 *
 * So the relay is a dead drop, not a key holder. Even someone reading its
 * database learns neither the room key nor which rooms belong together.
 *
 * The code is short enough to read aloud, which means it is also short enough
 * to guess if it lived forever. Three things bound that, and all three are
 * enforced by the relay rather than trusted to the client: the entry expires in
 * fifteen minutes, it is deleted the first time it is read, and there is a
 * rate limit per hash. A window that small against 32^8 (about a thousand
 * billion) possibilities is not a
 * meaningful attack surface — but it is a real trade, and it is why the code
 * carries an expiry and the QR does not.
 */

/** No 0/O or 1/I: they are the two mistakes people actually make reading aloud. */
const ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
const CODE_LEN = 8
/** Where the dash goes when the code is shown. Purely for reading. */
const GROUP = 4
const PBKDF2_ROUNDS = 250_000
const IV_BYTES = 12

export interface InviteSecret {
  roomId: string
  keyB64: string
  relayUrl: string
}

function toB64u(bytes: ArrayBuffer | Uint8Array): string {
  const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes)
  let s = ''
  for (const b of arr) s += String.fromCharCode(b)
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

function fromB64u(s: string): Uint8Array {
  const b64 = s.replace(/-/g, '+').replace(/_/g, '/')
  let bin: string
  try {
    bin = atob(b64.padEnd(Math.ceil(b64.length / 4) * 4, '='))
  } catch {
    throw new SyncError('base64')
  }
  const out = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
  return out
}

/**
 * Eight characters from the reduced alphabet.
 *
 * The alphabet is exactly 32 long, which divides 256 evenly, so taking each
 * random byte modulo 32 is unbiased — no rejection sampling needed. Shortening
 * the alphabet later would reintroduce the bias, hence the assertion below.
 */
export function randomCode(): string {
  let out = ''
  for (const b of crypto.getRandomValues(new Uint8Array(CODE_LEN))) {
    out += ALPHABET[b % ALPHABET.length]
  }
  return out
}

/**
 * What someone typed, turned into what was generated.
 *
 * People send these over chat, so they arrive lower-cased, with the dash still
 * in, wrapped in spaces, or quoted. All of that is the same code.
 */
export function normalizeCode(raw: string): string {
  // Everything the alphabet excludes — O, 0, I, 1 — is dropped rather than
  // guessed at. There is no correct character to map them onto, and silently
  // turning a typo into a different valid code would fail with a confusing
  // "kode salah" instead of an honest "kodenya kurang".
  return [...raw.toUpperCase()].filter((ch) => ALPHABET.includes(ch)).join('')
}

/** `K4MQ-7XR2` — dashed for reading, never for storage or hashing. */
export function formatCode(code: string): string {
  return code.length > GROUP ? `${code.slice(0, GROUP)}-${code.slice(GROUP)}` : code
}

export function isCodeShaped(raw: string): boolean {
  const c = normalizeCode(raw)
  return c.length === CODE_LEN && [...c].every((ch) => ALPHABET.includes(ch))
}

/** The relay's key for the drop. A hash, so the relay never holds the code. */
export async function codeHash(code: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(`temudua-invite/${code}`))
  // Half the digest is 128 bits — far past collision range for a 15-minute
  // window, and it keeps the URL path short.
  return toB64u(digest.slice(0, 16))
}

async function keyFromCode(code: string): Promise<CryptoKey> {
  const base = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(code) as BufferSource,
    'PBKDF2',
    false,
    ['deriveKey'],
  )
  return crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      // Salted by the code itself: there is no second channel to carry a salt,
      // and the entries are one-shot and short-lived, so a rainbow table would
      // have to be built for a room that no longer exists by the time it is.
      salt: new TextEncoder().encode(`temudua-invite-salt/${code}`) as BufferSource,
      iterations: PBKDF2_ROUNDS,
      hash: 'SHA-256',
    },
    base,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt'],
  )
}

export async function sealInvite(code: string, secret: InviteSecret): Promise<string> {
  const key = await keyFromCode(code)
  const iv = crypto.getRandomValues(new Uint8Array(IV_BYTES))
  const ct = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv: iv as BufferSource },
    key,
    new TextEncoder().encode(JSON.stringify(secret)) as BufferSource,
  )
  return `${toB64u(iv)}.${toB64u(ct)}`
}

export async function openInvite(code: string, blob: string): Promise<InviteSecret> {
  const [ivB64, ctB64] = blob.split('.')
  if (!ivB64 || !ctB64) throw new SyncError('invite blob')
  const key = await keyFromCode(code)
  let plain: ArrayBuffer
  try {
    plain = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: fromB64u(ivB64) as BufferSource },
      key,
      fromB64u(ctB64) as BufferSource,
    )
  } catch {
    // Wrong code and tampered blob are the same failure on purpose: telling
    // them apart would tell an attacker when they had the hash but not the code.
    throw new SyncError('invite code')
  }
  const parsed: unknown = JSON.parse(new TextDecoder().decode(plain))
  const s = parsed as Partial<InviteSecret>
  if (typeof s?.roomId !== 'string' || typeof s?.keyB64 !== 'string' || typeof s?.relayUrl !== 'string') {
    throw new SyncError('invite blob')
  }
  return { roomId: s.roomId, keyB64: s.keyB64, relayUrl: s.relayUrl }
}
