import { useState } from 'react'
import { Link } from 'react-router-dom'
import { Card, Field } from '@/components/ui'
import { Icon } from '@/design-system/Icon'
import { useI18n } from '@/i18n'
import { isCodeShaped } from './invite'
import { usePairing } from './usePairing'
import type { SyncConfig } from './engine'
import './sync.css'

/**
 * The whole of pairing, in one card.
 *
 * Lives in Settings as well as on the Sync screen, because "connect my
 * partner's phone" is a setup task and setup is where people look for it —
 * being one more navigation step away was most of why nobody found it.
 *
 * One phone presses the button and sends the message; the other taps the link
 * in it. Typing the code is the fallback, not the path.
 */
export default function PairPanel({
  relayOverride,
  onPaired,
  connectedCard = true,
}: {
  relayOverride?: string
  /** Lets the screen around the panel refresh its own view of the config. */
  onPaired?: (c: SyncConfig) => void
  /**
   * Whether to render the "already connected" card. The Sync screen shows a
   * fuller status card of its own, so it turns this off rather than saying the
   * same thing twice.
   */
  connectedCard?: boolean
}) {
  const { t } = useI18n()
  const p = usePairing(relayOverride, onPaired)
  const [draft, setDraft] = useState('')

  // `p.code` is checked first, and the order matters: making a code also
  // creates the room, so this phone has a config the instant it presses the
  // button. Checking `config` first would swap the code for "you are
  // connected" before the code had ever been on screen — the inviter would
  // have nothing to send. It is connected in the sense that it has a room;
  // nobody has joined it yet.
  if (p.config && !p.code) {
    if (!connectedCard) return null
    return (
      <Card title={t('sync.panel.connectedTitle')} icon="shared" hint={t('sync.panel.connectedHint')}>
        <p className="card__hint">{t('sync.panel.room', { room: p.config.roomId.slice(0, 8) })}</p>
      </Card>
    )
  }

  return (
    <Card title={t('sync.code.title')} icon="shared" hint={t('sync.code.hint')}>
      <div className="stack stack--tight">
        {p.notice && (
          <p className="banner" role="status">
            <Icon name="info" size={18} />
            {p.notice}
          </p>
        )}
        {p.error && (
          <p className="banner banner--danger" role="alert">
            {p.error}
          </p>
        )}

        {p.code ? (
          <>
            <p className="sync__bigcode">{p.code.slice(0, 4)}-{p.code.slice(4)}</p>
            <button
              type="button"
              className="btn btn--block"
              onClick={() => {
                const text = p.shareText ?? ''
                // The share sheet is the WhatsApp path, which is how these
                // actually travel. Clipboard where there is no share sheet.
                if (navigator.share) void navigator.share({ text }).catch(() => {})
                else void navigator.clipboard?.writeText(text).catch(() => {})
              }}
            >
              <Icon name="export" size={18} />
              {t('sync.code.send')}
            </button>
            <p className="disclaimer">{t('sync.code.expiry')}</p>
          </>
        ) : (
          <>
            <button
              type="button"
              className="btn btn--block"
              disabled={p.busy}
              onClick={() => void p.create()}
            >
              <Icon name="plus" size={18} />
              {t('sync.code.make')}
            </button>

            <p className="sync__or">{t('sync.code.or')}</p>

            <Field label={t('sync.code.enter')} hint={t('sync.code.enterHint')}>
              {(f) => (
                <input
                  {...f}
                  className="sync__codebox"
                  type="text"
                  autoCapitalize="characters"
                  autoComplete="off"
                  spellCheck={false}
                  placeholder="ABCD-2345"
                  value={draft}
                  onChange={(e) => {
                    setDraft(e.target.value)
                    // Eight characters is the whole code; asking for a button
                    // press after the last one is a step for its own sake.
                    if (isCodeShaped(e.target.value) && !p.busy) void p.redeem(e.target.value)
                  }}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') void p.redeem(draft)
                  }}
                />
              )}
            </Field>
            <button
              type="button"
              className="btn"
              disabled={p.busy || !isCodeShaped(draft)}
              onClick={() => void p.redeem(draft)}
            >
              <Icon name="check" size={18} />
              {t('sync.code.join')}
            </button>
          </>
        )}

        {!p.ready && (
          <p className="banner banner--warn">
            {t('sync.code.noRelay')}{' '}
            {/* The "Lanjutan" section it refers to lives on the Sync screen.
                Shown only where that is somewhere else — on the Sync screen
                itself the section is already a few centimetres below. */}
            {connectedCard && <Link to="/sinkron">{t('sync.code.noRelayLink')}</Link>}
          </p>
        )}
      </div>
    </Card>
  )
}
